package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.ruoyi.medical.contracts.*;
import java.time.*;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;

/** A genuine aggregate check, committed only after the combined findings/coverage
 * report was physically read and registered. Never a DOCUMENT or professional approval. */
public final class TaskCandidateAssemblyCheckService {
    private static final String EVENT="task.candidate_assembly.check.committed";
    private final JdbcTemplate db;private final TaskSourceVerifierSchema json;private final String schemaHash;
    public TaskCandidateAssemblyCheckService(DataSource data,TaskSourceVerifierSchema json)throws Exception{db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/task-candidate-assembly-check.schema.json"))){schemaHash=WireValues.sha256(in.readAllBytes());}}
    public Verified save(TaskCandidateAssemblyAuthority.Verified input,TaskCandidateAssemblyObjectLedger.Registered report)throws Exception{
        requireReport(input,report);var p=input.production();var prior=rows(input);if(!prior.isEmpty())return requireSaved(input,report);
        String id=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var at=LocalDateTime.now(ZoneOffset.UTC);var receipt=json.tree(Map.of("schema_version","1.0.0","check_id",id,"target_kind","CANDIDATE_SET","target_id",p.runId(),"target_revision",report.artifactId(),"input_sha256",input.inputSha256(),"report_artifact_id",report.artifactId(),"report_sha256",report.reference().sha256(),"report_receipt_sha256",report.receiptSha256()));var o=(com.fasterxml.jackson.databind.node.ObjectNode)receipt;o.put("audit_id",audit).put("event_id",event).put("status",input.ready()?"SUCCEEDED":"WAITING_INPUT").put("professional_approval",false).put("document_saved",false).put("n07_complete",false);o.set("blockers",json.tree(input.blockers()));o.set("input_watermarks",watermarks(input));
        validateReceipt(receipt);var row=meta(input,at);row.putAll(Map.of("check_id",id,"target_kind","CANDIDATE_SET","target_id",p.runId(),"target_revision",report.artifactId(),"input_sha256",input.inputSha256(),"scope_manifest_id",input.input().required("snapshot_id").asText(),"rule_manifest_id",input.ruleRevision(),"rule_manifest",json.canonical(input.ruleManifest()),"input_watermarks",json.canonical(watermarks(input))));
        // Aggregate watermarks are fully retained in input_watermarks, never collapsed
        // into a false document watermark. Scalar columns have no document target here.
        row.putAll(Map.of("evidence_watermark",0,"issue_watermark",0,"coverage_artifact_id",report.artifactId(),"findings_artifact_id",report.artifactId(),"result_ref",json.canonical(receipt),"run_id",p.runId(),"step_id",input.stepId(),"action_id",input.actionId(),"status",receipt.required("status").asText(),"revision",1));row.put("updated_at",at);insert("check_run",row);
        var a=meta(input,at);a.putAll(Map.of("audit_id",audit,"subject_id",p.actorId(),"action",EVENT,"resource_ref",json.canonical(receipt),"result","SUCCESS","request_id",input.actionId(),"trace_id",p.runId()));insert("audit_event",a);insert("outbox_event",Map.of("tenant_id",p.tenantId(),"event_id",event,"aggregate_id",id,"aggregate_revision",1,"event_type",EVENT,"payload",json.canonical(receipt),"occurred_at",at));return requireSaved(input,report);
    }
    public Verified requireSaved(TaskCandidateAssemblyAuthority.Verified input,TaskCandidateAssemblyObjectLedger.Registered report)throws Exception{requireReport(input,report);var row=one(rows(input));var receipt=json.read(str(row,"result_ref"));verify(input,report.artifactId(),report.receiptSha256(),receipt);return new Verified(input.inputSha256(),report.artifactId(),report.receiptSha256(),receipt);}
    private List<Map<String,Object>> rows(TaskCandidateAssemblyAuthority.Verified i){var p=i.production();return db.queryForList("SELECT * FROM check_run WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND target_kind='CANDIDATE_SET' LIMIT 2 FOR UPDATE",p.tenantId(),p.projectId(),p.runId(),i.stepId());}
    private void requireReport(TaskCandidateAssemblyAuthority.Verified i,TaskCandidateAssemblyObjectLedger.Registered r)throws Exception{if(r==null||!"CROSS_FILE_CHECK_REPORT".equals(r.kind()))bad();r.requireUnchanged();i.requireUnchanged();same(json.hash(i.crossFileReport()),r.reference().sha256());same(i.inputSha256(),r.receipt().required("input_sha256").asText());}
    private JsonNode watermarks(TaskCandidateAssemblyAuthority.Verified i){return i.input().required("candidates").deepCopy();}
    private void verify(TaskCandidateAssemblyAuthority.Verified i,String report,String reportReceipt,JsonNode receipt)throws Exception{
        validateReceipt(receipt);var p=i.production();var row=one(rows(i));same(receipt,json.read(str(row,"result_ref")));same(i.inputSha256(),str(row,"input_sha256"));same(p.runId(),str(row,"target_id"));same(report,str(row,"target_revision"));same(report,str(row,"coverage_artifact_id"));same(report,str(row,"findings_artifact_id"));same(i.ruleRevision(),str(row,"rule_manifest_id"));same(i.ruleManifest(),json.read(str(row,"rule_manifest")));same(watermarks(i),json.read(str(row,"input_watermarks")));same(i.input().required("snapshot_id").asText(),str(row,"scope_manifest_id"));same(i.ready()?"SUCCEEDED":"WAITING_INPUT",str(row,"status"));same(schemaHash,str(row,"schema_manifest_sha256"));same(p.actorId(),str(row,"created_by"));same(i.actionId(),str(row,"action_id"));
        same("CANDIDATE_SET",receipt.required("target_kind").asText());same(p.runId(),receipt.required("target_id").asText());same(report,receipt.required("target_revision").asText());same(str(row,"check_id"),receipt.required("check_id").asText());same(i.inputSha256(),receipt.required("input_sha256").asText());same(report,receipt.required("report_artifact_id").asText());same(reportReceipt,receipt.required("report_receipt_sha256").asText());same(json.hash(i.crossFileReport()),receipt.required("report_sha256").asText());same(watermarks(i),receipt.required("input_watermarks"));same(json.tree(i.blockers()),receipt.required("blockers"));same(str(row,"status"),receipt.required("status").asText());if(receipt.required("document_saved").asBoolean()||receipt.required("n07_complete").asBoolean()||receipt.required("professional_approval").asBoolean())bad();
        var a=one(db.queryForList("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND audit_id=? AND subject_id=? AND action=? AND result='SUCCESS' LIMIT 2",p.tenantId(),p.projectId(),receipt.required("audit_id").asText(),p.actorId(),EVENT));var e=one(db.queryForList("SELECT payload FROM outbox_event WHERE tenant_id=? AND event_id=? AND aggregate_id=? AND event_type=? LIMIT 2",p.tenantId(),receipt.required("event_id").asText(),str(row,"check_id"),EVENT));same(receipt,json.read(str(a,"resource_ref")));same(receipt,json.read(str(e,"payload")));
    }
    public final class Verified {private final String inputHash,report,reportReceipt;private final JsonNode receipt;private Verified(String hash,String report,String reportReceipt,JsonNode receipt){inputHash=hash;this.report=report;this.reportReceipt=reportReceipt;this.receipt=receipt.deepCopy();}public String checkId(){return receipt.required("check_id").asText();}public JsonNode receipt(){return receipt.deepCopy();}public void requireFor(TaskCandidateAssemblyAuthority.Verified i)throws Exception{same(inputHash,i.inputSha256());verify(i,report,reportReceipt,receipt);}}
    static void validateReceipt(JsonNode receipt)throws Exception{try(var in=Objects.requireNonNull(TaskCandidateAssemblyCheckService.class.getResourceAsStream("/task-candidate-assembly-check.schema.json"))){var schema=com.networknt.schema.JsonSchemaFactory.getInstance(com.networknt.schema.SpecVersion.VersionFlag.V202012).getSchema(new com.fasterxml.jackson.databind.ObjectMapper().readTree(in),com.networknt.schema.SchemaValidatorsConfig.builder().formatAssertionsEnabled(true).build());if(!schema.validate(receipt).isEmpty())bad();}}
    private Map<String,Object> meta(TaskCandidateAssemblyAuthority.Verified i,LocalDateTime at){var p=i.production();var m=new LinkedHashMap<String,Object>();m.put("tenant_id",p.tenantId());m.put("project_id",p.projectId());m.put("created_by",p.actorId());m.put("created_at",at);m.put("classification",p.classification());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",schemaHash);return m;}
    private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
    private static Map<String,Object> one(List<Map<String,Object>> rows){if(rows.size()!=1)bad();return rows.get(0);}private static String str(Map<String,Object> row,String key){return Objects.requireNonNull(row.get(key)).toString();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
